"""Cas propres au support. Ne jamais les remplacer par les corrigés du site.

Chaque figure utilise les données du cas voisin. Les résultats numériques sont
recalculés indépendamment dans verifier_exemples.py.
"""

def cas(enonce, pas, resultat, figure, lecture, question, hypothese, relation=None, mecanisme=None):
    return dict(enonce=enonce, pas=pas, resultat=resultat, figure=figure,
                lecture=lecture, question=question, hypothese=hypothese,
                relation=relation, mecanisme=mecanisme)

